unsigned checks=0;
void Check(bool ok,const std::string& name){++checks;if(!ok)throw std::runtime_error(name);}
Package Fixture(const std::string& id){Package p;p.manifest.id=id;p.manifest.name=id;p.manifest.version="1.0.0";p.manifest.game="lab";p.manifest.gameVersion="1.0.0";p.manifest.contractVersion="1.0.0";p.manifest.author="Judas";p.manifest.license="CC0";p.manifest.notices={"NOTICE.txt"};p.files["NOTICE.txt"]="Original fixture";p.manifest.files={{"NOTICE.txt",SceneFingerprintSha256(p.files.begin()->second),p.files.begin()->second.size()}};std::string bytes,e;Check(EncodePackage(p,bytes,e),"encode "+e);Check(DecodePackage(bytes,p,e),"decode "+e);return p;}
bool CheckedResolve(const Contract& c,std::initializer_list<Selection> values,Resolution& r,std::string& error){const std::vector<Selection> selected(values);return Resolve(c,selected,r,error);}
