 Contract c;c.enabled=true;c.executable=true;c.game="lab";c.gameVersion=c.version="1.0.0";c.registries=SceneFingerprintSha256("registries");c.additions={"mesh","script","scene"};Contract round;Check(ParseContract(ToJSON(c).dump(),round,e),"contract roundtrip "+e);
