 Manifest malformed;auto manifest=ToJSON(a->manifest);manifest["id"]="judas";Check(!ParseManifest(manifest.dump(),malformed,e),"reserved module identity");manifest=ToJSON(a->manifest);manifest["format"]=2;Check(!ParseManifest(manifest.dump(),malformed,e),"newer manifest rejected");manifest=ToJSON(a->manifest);manifest["name"]=std::string(Limits::Metadata+1,'x');Check(!ParseManifest(manifest.dump(),malformed,e),"metadata byte capacity");
