 auto root=fs::temp_directory_path()/"judas-m76-storage-tests";fs::remove_all(root);ContentStorage store(root.u8string());Check(store.Publish("old.judasmod","old",e,true),"publish "+e);std::string read;Check(store.Read("old.judasmod",read,128,e)&&read=="old","read");Check(!store.Publish("old.judasmod","changed",e,true),"immutable overwrite refused");auto lease=store.Lease("old.judasmod",e);Check(bool(lease),"lease");Check(!store.Remove("old.judasmod",e),"in-use remove refused");lease.reset();Check(store.Remove("old.judasmod",e),"release remove");Check(store.Publish("index.json","old",e),"index publication");store.boundary=[](const char* phase){if(std::string(phase)=="file-synced")throw std::runtime_error("injected interruption");};Check(!store.Publish("index.json","new",e),"interrupted publication");Check(store.Read("index.json",read,128,e)&&read=="old","last good retained");store.boundary={};Check(!store.Publish("../escape","x",e),"internal path refused");
