 std::vector<std::string> names;Check(store.List(names,128,e),"bounded listing "+e);Check(!store.List(names,0,e),"directory budget");Check(store.Publish("été.judasmod","unicode",e),"Unicode flat publication "+e);Check(store.Read("été.judasmod",read,128,e)&&read=="unicode","Unicode publication read");
 auto transactionRoot=root/"transactions";Store installs(transactionRoot.u8string());auto retained=Fixture("retained");Check(installs.Install(c,retained,e),"install immutable version "+e);Check(installs.Enable(c,"retained","1.0.0",retained.hash,false,e),"select data-only version "+e);Snapshot snapshot;Check(installs.Freeze(c,snapshot,e),"freeze whole session "+e);Check(installs.Disable("retained",e),"disable next launch");Check(!installs.Remove("retained","1.0.0",retained.hash,e),"in-use immutable version retained");snapshot={};Check(installs.Remove("retained","1.0.0",retained.hash,e),"released version removable "+e);
